<?php
require __DIR__ . '/includes/bootstrap.php';
$current=require_role('seller');
function product_error(string $message): never { flash($message,'error'); redirect('seller-products.php'); }
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['product_id']??0);
 if($action==='archive' || $action==='activate'){
  $stmt=$pdo->prepare('SELECT id FROM products WHERE id=? AND seller_id=?');$stmt->execute([$id,$current['id']]);if(!$stmt->fetch()) product_error('Produk tidak ditemukan di tokomu.');
  $active=$action==='activate'?1:0;$pdo->prepare('UPDATE products SET is_active=? WHERE id=? AND seller_id=?')->execute([$active,$id,$current['id']]);
  $pdo->prepare("INSERT INTO product_catalog_details(product_id,product_status) VALUES(?,?) ON DUPLICATE KEY UPDATE product_status=VALUES(product_status)")->execute([$id,$active?'active':'inactive']);
  $pdo->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data,ip_address) VALUES(?,?,?,?,?,?)")->execute([(int)$current['id'],$active?'product_activated':'product_archived','product',$id,json_encode(['is_active'=>$active]),$_SERVER['REMOTE_ADDR']??null]);
  flash($active?'Produk diaktifkan kembali.':'Produk diarsipkan.');redirect('seller-products.php');
 }
 if($action==='save'){
  $name=trim($_POST['name']??'');$category=trim($_POST['category']??'');$description=trim($_POST['description']??'');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_INT);$discountInput=trim($_POST['discount_price']??'');$discount=$discountInput===''?null:filter_var($discountInput,FILTER_VALIDATE_INT);$stock=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT);$sku=trim($_POST['sku']??'');$weight=filter_var($_POST['weight_grams']??null,FILTER_VALIDATE_INT);$status=$_POST['product_status']??'draft';$emoji=trim($_POST['emoji']??'🛍️');$color=trim($_POST['color']??'peach');
  if($name===''||$category===''||$description===''||$price===false||$price<1||$stock===false||$stock<0||($discountInput!==''&&($discount===false||$discount<1||$discount>=$price))||$weight===false||$weight<0||!in_array($status,['draft','active','inactive'],true)){product_error('Periksa nama, kategori, harga, stok, diskon, berat, dan status produk.');}
  if(strlen($name)>120||strlen($category)>60||strlen($description)>255||strlen($sku)>64) product_error('Panjang salah satu data melebihi batas.');
  $editId=(int)($_POST['product_id']??0);$old=null;if($editId){$q=$pdo->prepare('SELECT * FROM products WHERE id=? AND seller_id=?');$q->execute([$editId,$current['id']]);$old=$q->fetch();if(!$old)product_error('Produk tidak ditemukan di tokomu.');}
  $pdo->beginTransaction();
  try{
   if($editId){$q=$pdo->prepare('UPDATE products SET name=?,category=?,description=?,price=?,stock=?,emoji=?,color=?,is_active=? WHERE id=? AND seller_id=?');$q->execute([$name,$category,$description,$price,$stock,$emoji,$color,$status==='active'?1:0,$editId,$current['id']]);$productId=$editId;}
   else{$q=$pdo->prepare('INSERT INTO products(seller_id,name,category,description,price,stock,emoji,color,is_active) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([(int)$current['id'],$name,$category,$description,$price,$stock,$emoji,$color,$status==='active'?1:0]);$productId=(int)$pdo->lastInsertId();}
   $meta=$pdo->prepare('INSERT INTO product_catalog_details(product_id,sku,discount_price,weight_grams,product_status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE sku=VALUES(sku),discount_price=VALUES(discount_price),weight_grams=VALUES(weight_grams),product_status=VALUES(product_status)');$meta->execute([$productId,$sku===''?null:$sku,$discount,$weight,$status]);
   if(isset($_FILES['main_image'])&&$_FILES['main_image']['error']!==UPLOAD_ERR_NO_FILE){$file=$_FILES['main_image'];if($file['error']!==UPLOAD_ERR_OK||$file['size']>5242880)throw new RuntimeException('Foto utama maksimal 5 MB.');$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($extensions[$mime])||!getimagesize($file['tmp_name']))throw new RuntimeException('Foto harus berupa JPG, PNG, atau WebP yang valid.');$folder=__DIR__.'/images/products';if(!is_dir($folder)&&!mkdir($folder,0755,true)&&!is_dir($folder))throw new RuntimeException('Folder foto tidak dapat dibuat.');$filename=bin2hex(random_bytes(16)).'.'.$extensions[$mime];if(!move_uploaded_file($file['tmp_name'],$folder.'/'.$filename))throw new RuntimeException('Foto gagal diunggah.');$path='images/products/'.$filename;$pdo->prepare('DELETE FROM product_images WHERE product_id=?')->execute([$productId]);$pdo->prepare('INSERT INTO product_images(product_id,image_path,alt_text,sort_order) VALUES(?,?,?,0)')->execute([$productId,$path,$name]);}
   $pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data,ip_address) VALUES(?,?,?,?,?,?)')->execute([(int)$current['id'],$editId?'product_updated':'product_created','product',$productId,json_encode(['name'=>$name,'price'=>$price,'stock'=>$stock,'status'=>$status]),$_SERVER['REMOTE_ADDR']??null]);$pdo->commit();flash($editId?'Produk berhasil diperbarui.':'Produk berhasil ditambahkan.');redirect('seller-products.php');
  }catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();if($exception instanceof PDOException&&$exception->getCode()==='23000')product_error('SKU sudah dipakai produk lain.');product_error($exception instanceof RuntimeException?$exception->getMessage():'Produk belum tersimpan. Periksa migration dan data yang kamu masukkan.');}
 }
 http_response_code(400);exit('Aksi produk tidak dikenal.');
}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT p.*,d.sku,d.discount_price,d.weight_grams,d.product_status,i.image_path FROM products p LEFT JOIN product_catalog_details d ON d.product_id=p.id LEFT JOIN product_images i ON i.product_id=p.id AND i.sort_order=0 WHERE p.id=? AND p.seller_id=?');$q->execute([(int)$_GET['edit'],$current['id']]);$edit=$q->fetch();if(!$edit)product_error('Produk tidak ditemukan di tokomu.');}
$list=$pdo->prepare('SELECT p.*,d.sku,d.discount_price,d.weight_grams,d.product_status,i.image_path FROM products p LEFT JOIN product_catalog_details d ON d.product_id=p.id LEFT JOIN product_images i ON i.product_id=p.id AND i.sort_order=0 WHERE p.seller_id=? ORDER BY p.created_at DESC');$list->execute([(int)$current['id']]);$products=$list->fetchAll();
layout_start('Produk saya');show_flash();
?>
<section class="dashboard-heading"><div><span class="eyebrow">TOKO SAYA</span><h1>Kelola produk</h1><p>Data katalog hanya dapat diubah oleh pemilik produk.</p></div><a class="button button-light" href="dashboard.php">Kembali ke dashboard</a></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow"><?= $edit?'PERBARUI KATALOG':'KATALOG BARU' ?></span><h2><?= $edit?'Edit produk':'Tambah produk' ?></h2></div></div><form method="post" enctype="multipart/form-data" class="product-create-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="product_id" value="<?=(int)($edit['id']??0)?>"><label>Nama produk<input name="name" required maxlength="120" value="<?=h($edit['name']??'')?>"></label><label>Kategori<input name="category" required maxlength="60" value="<?=h($edit['category']??'')?>"></label><label>Harga (Rp)<input name="price" type="number" min="1" required value="<?=h($edit['price']??'')?>"></label><label>Harga diskon (Rp) <small>Opsional</small><input name="discount_price" type="number" min="1" value="<?=h($edit['discount_price']??'')?>"></label><label>Stok<input name="stock" type="number" min="0" required value="<?=h($edit['stock']??0)?>"></label><label>SKU / kode produk<input name="sku" maxlength="64" value="<?=h($edit['sku']??'')?>"></label><label>Berat (gram)<input name="weight_grams" type="number" min="0" value="<?=h($edit['weight_grams']??0)?>"></label><label>Status<select name="product_status"><option value="draft" <?=($edit['product_status']??'draft')==='draft'?'selected':''?>>Draft</option><option value="active" <?=($edit['product_status']??'')==='active'?'selected':''?>>Aktif</option><option value="inactive" <?=($edit['product_status']??'')==='inactive'?'selected':''?>>Nonaktif</option></select></label><label>Emoji kartu<input name="emoji" maxlength="12" value="<?=h($edit['emoji']??'🛍️')?>"></label><label>Warna kartu<input name="color" maxlength="30" value="<?=h($edit['color']??'peach')?>"></label><label class="wide-field">Deskripsi<input name="description" maxlength="255" required value="<?=h($edit['description']??'')?>"></label><label class="wide-field">Foto utama (JPG, PNG, WebP; maks. 5 MB)<input type="file" name="main_image" accept="image/jpeg,image/png,image/webp"></label><?php if(!empty($edit['image_path'])): ?><p class="wide-field">Foto saat ini: <img src="<?=h($edit['image_path'])?>" alt="Foto produk" width="64"></p><?php endif; ?><button class="button button-dark"><?= $edit?'Simpan perubahan':'Terbitkan produk' ?></button><?php if($edit): ?><a class="button button-light" href="seller-products.php">Batal edit</a><?php endif; ?></form></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">DAFTAR PRODUK</span><h2>Inventaris saya</h2></div></div><div class="table-wrap"><table><thead><tr><th>Produk</th><th>SKU</th><th>Harga</th><th>Stok</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?=h($p['name'])?><small><?=h($p['category'])?></small></td><td><?=h($p['sku']??'—')?></td><td><?=rupiah((int)$p['price'])?><?php if($p['discount_price']): ?><small>Promo <?=rupiah((int)$p['discount_price'])?></small><?php endif; ?></td><td><?=(int)$p['stock']?></td><td><?=h(ucfirst($p['product_status']??($p['is_active']?'active':'inactive')))?></td><td><a class="button button-light" href="seller-products.php?edit=<?=(int)$p['id']?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="button button-light" name="action" value="<?=$p['is_active']?'archive':'activate'?>"><?=$p['is_active']?'Arsipkan':'Aktifkan'?></button></form></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="6">Belum ada produk. Gunakan formulir di atas untuk menambah produk pertamamu.</td></tr><?php endif; ?></tbody></table></div></section>
<?php layout_end(); ?>